  KEY `idx_refresh_user` (`user_id`,`user_type`),
  KEY `idx_refresh_expires` (`expires_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3689 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `permission_groups`;
CREATE TABLE `permission_groups` (
