  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `order_items_financial_fix_backup_20260302`;
CREATE TABLE `order_items_financial_fix_backup_20260302` (
  `id` int(11) NOT NULL DEFAULT 0,
