  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_store_status_message_store` (`store_id`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `rider_day_closings`;
CREATE TABLE `rider_day_closings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rider_id` int(11) NOT NULL,
  `closed_date` date NOT NULL,
  `wallet_balance` decimal(12,2) NOT NULL DEFAULT 0.00,
  `cash_collection` decimal(12,2) NOT NULL DEFAULT 0.00,
  `office_advance` decimal(12,2) NOT NULL DEFAULT 0.00,
  `store_payment` decimal(12,2) NOT NULL DEFAULT 0.00,
  `fuel_payment` decimal(12,2) NOT NULL DEFAULT 0.00,
  `delivery_fee_earned` decimal(12,2) NOT NULL DEFAULT 0.00,
