  `closed_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_rider_close_day` (`rider_id`,`closed_date`),
  KEY `idx_rider_close_day` (`rider_id`,`closed_date`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `financial_reports`;
CREATE TABLE `financial_reports` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `report_number` varchar(50) NOT NULL,
  `report_type` enum('daily_summary','weekly_summary','monthly_summary','store_settlement','rider_cash_report','rider_orders_report','rider_payments_report','rider_receivings_report','rider_wallet_report','rider_petrol_report','rider_daily_mileage_report','rider_daily_activity_report','rider_day_closing_report','order_profit_report','expense_report','general_voucher','store_financials','rider_fuel_report','comprehensive_report','store_payable_reconciliation','unsettled_amounts_report','cash_discrepancy_report','store_order_settlement_report','delivery_charges_breakdown','order_wise_sale_summary','periodic_sales_report','periodic_credit_cash_report','periodic_comprehensive_summary_report','periodic_store_payments_balance_report','transaction_summary','custom') NOT NULL,
  `period_from` date DEFAULT NULL,
  `period_to` date DEFAULT NULL,
  `total_income` decimal(12,2) DEFAULT 0.00,
  `total_expense` decimal(12,2) DEFAULT 0.00,
  `total_commissions` decimal(12,2) DEFAULT 0.00,
  `net_profit` decimal(12,2) DEFAULT 0.00,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`data`)),
  `generated_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `description` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `report_number` (`report_number`),
  KEY `generated_by` (`generated_by`),
  KEY `idx_fr_report_type` (`report_type`),
  KEY `idx_fr_period_from` (`period_from`),
  CONSTRAINT `financial_reports_ibfk_1` FOREIGN KEY (`generated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `user_permissions`;
CREATE TABLE `user_permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `permission_key` varchar(100) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
